{"implementation":"def solve(case):
    data = case.get("payload", case)
    threshold = data["threshold"]
    retained = []

    for call in data["calls"]:
        if not call["parseable"]:
            continue
        token_count = call["prediction_tokens"]
        if token_count <= 0:
            continue
        effect_per_token = (
            call["loss_without_call"] - call["loss_with_call"]
        ) / token_count
        if effect_per_token >= threshold:
            retained.append(call["call_id"])

    return retained
"}
